mapper.sql:
FROM srv_inspection_rule_revision r
JOIN srv_inspection_rule i
  ON i.tenant_id = r.tenant_id
 AND i.id = r.rule_id
 AND i.deleted = b'0'
WHERE r.tenant_id = #{query.tenantId}
  AND r.deleted = b'0'

  AND i.detection_id = #{query.detectionId}


  AND i.rule_name LIKE CONCAT('%', #{query.ruleNameKeyword}, '%')


  AND r.category_code = #{query.categoryCode}


  AND r.severity_code = #{query.severityCode}


  AND r.status_code = #{query.statusCode}


  AND EXISTS (
    SELECT 1
    FROM srv_inspection_rule_product_type_revision p
    WHERE p.tenant_id = r.tenant_id
      AND p.revision_id = r.id
      AND p.deleted = b'0'
      AND p.product_type_code = #{query.productTypeCode}
  )

mapper.select:
SELECT r.*

ORDER BY r.rule_id, r.revision_no DESC, r.id DESC
LIMIT #{query.offset}, #{query.pageSize}

mapper.update:
UPDATE srv_inspection_rule_revision
SET status_code = 'DISABLED',
    disabled_by = #{command.disabledBy},
    disabled_at = #{command.disabledAt},
    version = version + 1
WHERE tenant_id = #{command.tenantId}
  AND id = #{command.revisionId}
  AND status_code = 'PUBLISHED'
  AND version = #{command.expectedVersion}
  AND deleted = b'0'

mapper.select:
SELECT MAX(revision_no)
FROM srv_inspection_rule_revision
WHERE tenant_id = #{query.tenantId}
  AND rule_id = #{query.ruleId}
  AND deleted = b'0'
